-- +goose Up
-- Data model: Project -> Repo -> Worktree -> Task -> Change set
-- (docs/AGENTS.md 5.1). IDs are opaque text generated by the application.
-- Times are RFC 3339 UTC text. JSON columns hold JSON text.

CREATE TABLE projects (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL UNIQUE,
    path       TEXT NOT NULL,
    created_at TEXT NOT NULL
) STRICT;

CREATE TABLE repos (
    id             TEXT PRIMARY KEY,
    project_id     TEXT    NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    name           TEXT    NOT NULL,
    path           TEXT    NOT NULL,
    default_branch TEXT    NOT NULL DEFAULT '',
    -- SF-09: the user accepted the repo's own agent hooks and MCP servers.
    trusted        INTEGER NOT NULL DEFAULT 0 CHECK (trusted IN (0, 1)),
    created_at     TEXT    NOT NULL,
    UNIQUE (project_id, name)
) STRICT;

CREATE INDEX repos_project_id ON repos (project_id);

-- AG-23: parent_task_id is a relation between tasks, one level only
-- (enforced by the triggers below). It is in the first migration so later
-- phases add behaviour, not schema.
CREATE TABLE tasks (
    id             TEXT PRIMARY KEY,
    project_id     TEXT NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    parent_task_id TEXT REFERENCES tasks (id) ON DELETE CASCADE,
    title          TEXT NOT NULL,
    prompt         TEXT NOT NULL,
    scope          TEXT NOT NULL CHECK (scope IN ('repo', 'project')),
    mode           TEXT NOT NULL CHECK (mode IN ('ask', 'code', 'current_branch', 'project')),
    agent          TEXT NOT NULL,
    model          TEXT NOT NULL DEFAULT '',
    status         TEXT NOT NULL CHECK (status IN
                       ('draft', 'queued', 'running', 'needs_you', 'review', 'done', 'failed', 'cancelled')),
    session_id     TEXT NOT NULL DEFAULT '',
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL,
    finished_at    TEXT,
    CHECK (parent_task_id IS NULL OR parent_task_id <> id)
) STRICT;

CREATE INDEX tasks_project_id ON tasks (project_id);
CREATE INDEX tasks_parent_task_id ON tasks (parent_task_id);
CREATE INDEX tasks_status ON tasks (status);

-- +goose StatementBegin
-- A task that has a parent cannot be a parent (AG-24).
CREATE TRIGGER tasks_one_level_insert
BEFORE INSERT ON tasks
WHEN NEW.parent_task_id IS NOT NULL
    AND (SELECT parent_task_id FROM tasks WHERE id = NEW.parent_task_id) IS NOT NULL
BEGIN
    SELECT RAISE(ABORT, 'sub-tasks are one level only');
END;
-- +goose StatementEnd

-- +goose StatementBegin
CREATE TRIGGER tasks_one_level_update
BEFORE UPDATE OF parent_task_id ON tasks
WHEN NEW.parent_task_id IS NOT NULL
    AND ((SELECT parent_task_id FROM tasks WHERE id = NEW.parent_task_id) IS NOT NULL
         OR EXISTS (SELECT 1 FROM tasks WHERE parent_task_id = NEW.id))
BEGIN
    SELECT RAISE(ABORT, 'sub-tasks are one level only');
END;
-- +goose StatementEnd

-- Repos in a task's scope.
CREATE TABLE task_repos (
    task_id TEXT NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    repo_id TEXT NOT NULL REFERENCES repos (id) ON DELETE CASCADE,
    PRIMARY KEY (task_id, repo_id)
) STRICT, WITHOUT ROWID;

-- AG-25: a task starts after its siblings in this table. Acyclic order is
-- validated by the application when the sub-tasks are created.
CREATE TABLE task_dependencies (
    task_id            TEXT NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    depends_on_task_id TEXT NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    PRIMARY KEY (task_id, depends_on_task_id),
    CHECK (task_id <> depends_on_task_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE worktrees (
    id         TEXT PRIMARY KEY,
    repo_id    TEXT NOT NULL REFERENCES repos (id) ON DELETE CASCADE,
    task_id    TEXT NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    name       TEXT NOT NULL,
    path       TEXT NOT NULL,
    branch     TEXT NOT NULL,
    status     TEXT NOT NULL CHECK (status IN ('active', 'merged', 'removed')),
    created_at TEXT NOT NULL,
    UNIQUE (repo_id, name)
) STRICT;

CREATE INDEX worktrees_task_id ON worktrees (task_id);

-- Normalized agent events, replayed to rebuild a transcript (AG-14).
CREATE TABLE task_events (
    task_id TEXT    NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    seq     INTEGER NOT NULL,
    kind    TEXT    NOT NULL,
    at      TEXT    NOT NULL,
    -- The whole agents.Event as JSON.
    data    TEXT    NOT NULL CHECK (json_valid(data)),
    PRIMARY KEY (task_id, seq)
) STRICT, WITHOUT ROWID;

CREATE TABLE change_sets (
    id          TEXT PRIMARY KEY,
    task_id     TEXT NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    status      TEXT NOT NULL CHECK (status IN ('open', 'shipped', 'closed')),
    -- JSON array of repo IDs (RV-04).
    merge_order TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(merge_order)),
    created_at  TEXT NOT NULL
) STRICT;

CREATE INDEX change_sets_task_id ON change_sets (task_id);

CREATE TABLE proposals (
    id            TEXT PRIMARY KEY,
    change_set_id TEXT REFERENCES change_sets (id) ON DELETE CASCADE,
    task_id       TEXT REFERENCES tasks (id) ON DELETE SET NULL,
    repo_id       TEXT REFERENCES repos (id) ON DELETE SET NULL,
    kind          TEXT NOT NULL CHECK (kind IN
                      ('commit', 'push', 'merge_request', 'install', 'publish',
                       'agent_file', 'delete_files', 'subtasks')),
    status        TEXT NOT NULL CHECK (status IN ('pending', 'confirmed', 'rejected', 'executed', 'failed')),
    summary       TEXT NOT NULL,
    -- Kind-specific JSON; never holds tokens.
    payload       TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(payload)),
    created_at    TEXT NOT NULL,
    decided_at    TEXT
) STRICT;

CREATE INDEX proposals_status ON proposals (status);
CREATE INDEX proposals_change_set_id ON proposals (change_set_id);

CREATE TABLE builds (
    id          TEXT PRIMARY KEY,
    worktree_id TEXT REFERENCES worktrees (id) ON DELETE SET NULL,
    task_id     TEXT REFERENCES tasks (id) ON DELETE SET NULL,
    status      TEXT NOT NULL CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'cancelled')),
    created_at  TEXT NOT NULL,
    finished_at TEXT
) STRICT;

CREATE TABLE build_steps (
    build_id    TEXT    NOT NULL REFERENCES builds (id) ON DELETE CASCADE,
    idx         INTEGER NOT NULL,
    repo_id     TEXT    NOT NULL REFERENCES repos (id) ON DELETE CASCADE,
    name        TEXT    NOT NULL,
    status      TEXT    NOT NULL CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'cancelled')),
    exit_code   INTEGER,
    log_path    TEXT    NOT NULL DEFAULT '',
    started_at  TEXT,
    finished_at TEXT,
    PRIMARY KEY (build_id, idx)
) STRICT, WITHOUT ROWID;

-- SF-05: append-only. Detail is redacted before it is written.
CREATE TABLE audit_log (
    id      TEXT PRIMARY KEY,
    at      TEXT NOT NULL,
    actor   TEXT NOT NULL,
    action  TEXT NOT NULL,
    subject TEXT NOT NULL,
    detail  TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(detail))
) STRICT;

CREATE INDEX audit_log_at ON audit_log (at);
CREATE INDEX audit_log_subject ON audit_log (subject);

-- +goose StatementBegin
CREATE TRIGGER audit_log_no_update
BEFORE UPDATE ON audit_log
BEGIN
    SELECT RAISE(ABORT, 'the audit log is append-only');
END;
-- +goose StatementEnd

-- +goose StatementBegin
CREATE TRIGGER audit_log_no_delete
BEFORE DELETE ON audit_log
BEGIN
    SELECT RAISE(ABORT, 'the audit log is append-only');
END;
-- +goose StatementEnd

-- +goose Down
DROP TRIGGER audit_log_no_delete;
DROP TRIGGER audit_log_no_update;
DROP TABLE audit_log;
DROP TABLE build_steps;
DROP TABLE builds;
DROP TABLE proposals;
DROP TABLE change_sets;
DROP TABLE task_events;
DROP TABLE worktrees;
DROP TABLE task_dependencies;
DROP TABLE task_repos;
DROP TRIGGER tasks_one_level_update;
DROP TRIGGER tasks_one_level_insert;
DROP TABLE tasks;
DROP TABLE repos;
DROP TABLE projects;
